create or replace function app_private.validate_profile_phone() returns trigger
language plpgsql security definer set search_path='' as $$
declare c public.phone_country_codes; n text;
begin
 if TG_OP='UPDATE' and new.phone is not distinct from old.phone and new.phone_country_iso2 is not distinct from old.phone_country_iso2 and new.phone_national is not distinct from old.phone_national and new.phone_e164 is not distinct from old.phone_e164 and new.phone_calling_code is not distinct from old.phone_calling_code then return new; end if;
 new.phone_country_iso2:=nullif(upper(trim(coalesce(new.phone_country_iso2,''))),'');
 n:=nullif(trim(coalesce(new.phone_national,'')),'');
 if new.phone_country_iso2 is null and n is null and new.phone is null then
   new.phone_national:=null;new.phone_calling_code:=null;new.phone_e164:=null;return new;
 end if;
 if new.phone_country_iso2 is null or n is null then raise exception 'Select a country and enter its phone number.'; end if;
 select * into c from public.phone_country_codes where iso2=new.phone_country_iso2;
 if c.iso2 is null or c.national_pattern is null or n !~ '^[0-9]+$' or not (length(n)=any(c.possible_lengths)) or n !~ c.national_pattern or (c.leading_digits is not null and n !~ ('^(?:'||c.leading_digits||')')) or length(c.calling_code||n)>16 then
   raise exception 'Enter a valid phone number for the selected country.';
 end if;
 if TG_OP='UPDATE' and new.phone is distinct from old.phone and new.phone_national is not distinct from old.phone_national and new.phone_country_iso2 is not distinct from old.phone_country_iso2 and new.phone is distinct from n::numeric then raise exception 'Update the country and national phone number together.'; end if;
 new.phone_national:=n;new.phone:=n::numeric;new.phone_calling_code:=c.calling_code;new.phone_e164:=c.calling_code||n;
 return new;
end $$;
revoke all on function app_private.validate_profile_phone() from public,anon,authenticated;
drop trigger if exists validate_profile_phone on public.users;
create trigger validate_profile_phone before insert or update on public.users for each row execute function app_private.validate_profile_phone();

CREATE OR REPLACE FUNCTION app_private.protect_user_privileged_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
begin
  if auth.uid() is not null and not app_private.is_admin() then
    if new.daily_task_limit is distinct from old.daily_task_limit or new.id is distinct from old.id or new.email is distinct from old.email or new."uniqueID" is distinct from old."uniqueID" or new.balance is distinct from old.balance or new.role is distinct from old.role or new."accountStatus" is distinct from old."accountStatus" then
      raise exception 'Protected user fields cannot be modified';
    end if;
  end if;
  return new;
end $function$;


CREATE OR REPLACE FUNCTION public.update_my_profile(p_full_name text, p_dob date, p_education text, p_occupation text, p_country_iso2 text, p_national_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_iso text:=nullif(upper(trim(coalesce(p_country_iso2,''))),''); v_national text:=nullif(trim(coalesce(p_national_phone,'')),'');
begin
 if auth.uid() is null then raise exception 'NOT_AUTHENTICATED'; end if;
 if not app_private.is_active_user() then raise exception 'PLATFORM_ACCESS_REQUIRED'; end if;
 if nullif(trim(coalesce(p_full_name,'')),'') is null then raise exception 'FULL_NAME_REQUIRED'; end if;
 update public.users set "fullName"=trim(p_full_name),"Date of Birth"=p_dob,education=nullif(trim(coalesce(p_education,'')),''),occupation=nullif(trim(coalesce(p_occupation,'')),''),phone_country_iso2=v_iso,phone_national=v_national,phone=case when v_national is null then null when v_national ~ '^[0-9]+$' then v_national::numeric else null end,"lastOnline"=now() where id=auth.uid();
 return public.get_my_account_controls();
end $function$;


-- An immutable work ledger prevents reassignment/deletion from resetting consumption.
create table if not exists app_private.daily_task_starts(
 user_id uuid not null references public.users(id) on delete cascade,
 work_key text not null,
 task_id integer,
 started_at timestamptz not null default now(),
 primary key(user_id,work_key)
);
alter table app_private.daily_task_starts enable row level security;
revoke all on app_private.daily_task_starts from public,anon,authenticated;
create index if not exists daily_task_starts_user_time_idx on app_private.daily_task_starts(user_id,started_at);
insert into app_private.daily_task_starts(user_id,work_key,task_id,started_at)
 select u.id,'task:'||t.id,t.id,t.started_at from public.tasks t join public.users u on lower(t."assignedTo") in (lower(u.email),lower(u."uniqueID")) where t.started_at is not null and coalesce(t.layer,'L1')<>'L2'
 on conflict do nothing;
insert into app_private.daily_task_starts(user_id,work_key,task_id,started_at)
 select reviewer_id,'review:'||submission_id,reviewer_task_id,claimed_at from public.voice_l2_review_claims on conflict do nothing;
create or replace function app_private.consume_daily_work_slot(p_task_id integer,p_user_id uuid,p_work_key text) returns void
language plpgsql security definer set search_path='' as $$
declare u public.users; t public.tasks; used integer; day_start timestamptz;
begin
 if auth.uid() is null then raise exception 'NOT_AUTHENTICATED'; end if;
 select * into u from public.users where id=p_user_id for update;
 if u.id is null or u."accountStatus"<>'active' then raise exception 'PLATFORM_ACCESS_REQUIRED'; end if;
 select * into t from public.tasks where id=p_task_id for update;
 if t.id is null or t.status<>'pending' or not coalesce(lower(t."assignedTo") in (lower(u.email),lower(u."uniqueID")),false) then raise exception 'TASK_NOT_AVAILABLE'; end if;
 if exists(select 1 from app_private.daily_task_starts s where s.user_id=u.id and s.work_key=p_work_key) then return; end if;
 day_start:=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC';
 select count(*) into used from app_private.daily_task_starts s where s.user_id=u.id and s.started_at>=day_start and s.started_at<day_start+interval '1 day';
 if u.daily_task_limit is not null and used>=u.daily_task_limit then raise exception 'DAILY_TASK_LIMIT_REACHED:%',u.daily_task_limit; end if;
 insert into app_private.daily_task_starts(user_id,work_key,task_id) values(u.id,p_work_key,t.id);
 update public.tasks set started_at=coalesce(started_at,now()) where id=t.id;
end $$;
revoke all on function app_private.consume_daily_work_slot(integer,uuid,text) from public,anon,authenticated;
create or replace function app_private.consume_daily_task_slot(p_task_id integer,p_user_id uuid) returns void
language plpgsql security definer set search_path='' as $$
begin perform app_private.consume_daily_work_slot(p_task_id,p_user_id,'task:'||p_task_id); end $$;
revoke all on function app_private.consume_daily_task_slot(integer,uuid) from public,anon,authenticated;

CREATE OR REPLACE FUNCTION public.get_my_account_controls()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_u public.users; v_used integer:=0; v_remaining integer; v_day_start timestamptz; v_legacy_phone text;
begin
  if auth.uid() is null then raise exception 'NOT_AUTHENTICATED'; end if;
  select * into v_u from public.users where id=auth.uid();
  if v_u.id is null then raise exception 'PROFILE_NOT_FOUND'; end if;
  v_day_start:=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC';
  select count(*) into v_used from app_private.daily_task_starts s where s.user_id=v_u.id and s.started_at>=v_day_start and s.started_at<v_day_start+interval '1 day';
  v_remaining:=case when v_u.daily_task_limit is null then null else greatest(v_u.daily_task_limit-v_used,0) end;
  v_legacy_phone:=case when v_u.phone is null then null else regexp_replace(v_u.phone::text,'\.0+$','','') end;
  return jsonb_build_object('phone_country_iso2',v_u.phone_country_iso2,'phone_calling_code',v_u.phone_calling_code,'phone_national',coalesce(v_u.phone_national,v_legacy_phone),'phone_e164',v_u.phone_e164,'daily_task_limit',v_u.daily_task_limit,'daily_tasks_started_today',v_used,'daily_tasks_remaining',v_remaining,'daily_limit_timezone','UTC','resets_at',v_day_start+interval '1 day');
end $function$;


CREATE OR REPLACE FUNCTION public.admin_set_daily_task_limit(p_user_id uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_admin public.users; v_target public.users; v_used integer:=0; v_day_start timestamptz;
begin
  select * into v_admin from public.users where id=auth.uid();
  if v_admin.id is null or v_admin.role<>'admin' or v_admin."accountStatus"<>'active' then raise exception 'ACTIVE_ADMIN_REQUIRED'; end if;
  if p_limit is not null and (p_limit<0 or p_limit>10000) then raise exception 'LIMIT_MUST_BE_0_TO_10000_OR_NULL'; end if;
  update public.users set daily_task_limit=p_limit where id=p_user_id returning * into v_target;
  if v_target.id is null then raise exception 'USER_NOT_FOUND'; end if;
  v_day_start:=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC';
  select count(*) into v_used from app_private.daily_task_starts s where s.user_id=v_target.id and s.started_at>=v_day_start and s.started_at<v_day_start+interval '1 day';
  return jsonb_build_object('user_id',v_target.id,'daily_task_limit',p_limit,'started_today',v_used,'remaining',case when p_limit is null then null else greatest(p_limit-v_used,0) end,'timezone','UTC','resets_at',v_day_start+interval '1 day');
end $function$;


CREATE OR REPLACE FUNCTION public.admin_get_daily_task_limits()
 RETURNS TABLE(user_id uuid, daily_task_limit integer, started_today integer, remaining integer, resets_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_admin public.users; v_day_start timestamptz;
begin
  select * into v_admin from public.users where id=auth.uid();
  if v_admin.id is null or v_admin.role<>'admin' or v_admin."accountStatus"<>'active' then raise exception 'ACTIVE_ADMIN_REQUIRED'; end if;
  v_day_start:=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC';
  return query select u.id,u.daily_task_limit,count(s.work_key)::integer,case when u.daily_task_limit is null then null else greatest(u.daily_task_limit-count(s.work_key)::integer,0) end,v_day_start+interval '1 day' from public.users u left join app_private.daily_task_starts s on s.user_id=u.id and s.started_at>=v_day_start and s.started_at<v_day_start+interval '1 day' group by u.id,u.daily_task_limit order by u."fullName" nulls last,u.email;
end $function$;

CREATE OR REPLACE FUNCTION public.begin_assigned_task(p_task_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_u public.users; v_t public.tasks; v_controls jsonb;
begin
  select * into v_u from public.users where id=auth.uid() for update;
  if v_u.id is null then raise exception 'NOT_AUTHENTICATED'; end if;
  if v_u."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'PLATFORM_ACCESS_REQUIRED'; end if;
  select * into v_t from public.tasks where id=p_task_id and status='pending' and ("assignedTo"=v_u.email or "assignedTo"=v_u."uniqueID") limit 1;
  if v_t.id is null then raise exception 'TASK_NOT_AVAILABLE'; end if;
  if not app_private.has_project_access(v_t.title) then raise exception 'PROJECT_ACCESS_REVOKED'; end if;
  if v_t.layer='L1' then perform app_private.consume_daily_task_slot(v_t.id,v_u.id); end if;
  v_controls:=public.get_my_account_controls();
  return jsonb_build_object('task_id',v_t.id,'public_task_id',v_t.public_task_id,'started_at',(select started_at from public.tasks where id=v_t.id),'daily',v_controls);
end $function$;


CREATE OR REPLACE FUNCTION public.submit_assigned_task(p_task_id integer, p_audio_data text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_task public.tasks; v_user public.users; v_id integer;
begin
 select * into v_user from public.users where id=auth.uid() for update;
 if v_user.id is null then raise exception 'Not authenticated'; end if;
 if v_user."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'Platform access required'; end if;
 select * into v_task from public.tasks where id=p_task_id and status='pending' and ("assignedTo"=v_user.email or "assignedTo"=v_user."uniqueID") for update;
 if v_task.id is null then raise exception 'Task not available'; end if;
 if not app_private.has_project_access(v_task.title) then raise exception 'Project access revoked'; end if;
 perform app_private.consume_daily_task_slot(v_task.id,v_user.id);
 insert into public.submissions("workerUID","projectTitle","earnedAmount","audioData",status,task_id)
 values(v_user."uniqueID",v_task.title,coalesce(v_task.price,0),p_audio_data,'Pending',v_task.id)
 returning id into v_id;
 update public.tasks set status='submitted' where id=v_task.id;
 return v_id;
end
$function$;


CREATE OR REPLACE FUNCTION public.review_submission(p_task_id integer, p_submission_id integer, p_decision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_u public.users; v_t public.tasks;
begin
 if p_decision not in ('Reviewed','Rejected') then raise exception 'Invalid review decision'; end if;
 select * into v_u from public.users where id=auth.uid() for update;
 if v_u.id is null then raise exception 'Not authenticated'; end if;
 if v_u."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'Platform access required'; end if;
 select * into v_t from public.tasks where id=p_task_id and layer='L2' and status='pending' and ("assignedTo"=v_u.email or "assignedTo"=v_u."uniqueID") for update;
 if v_t.id is null then raise exception 'Reviewer assignment not found'; end if;
 if not app_private.has_project_access(v_t.title) then raise exception 'Project access revoked'; end if;
 if not exists(select 1 from public.submissions where id=p_submission_id and "projectTitle"=v_t.title and coalesce(status,'Pending')='Pending') then raise exception 'Submission unavailable'; end if;
 perform app_private.consume_daily_work_slot(v_t.id,v_u.id,'review:'||p_submission_id);
 update public.submissions
 set status=p_decision,
     reviewed_at=case when p_decision='Reviewed' then now() else reviewed_at end,
     rejected_at=case when p_decision='Rejected' then now() else rejected_at end
 where id=p_submission_id;
 if not exists(select 1 from public.submissions where "projectTitle"=v_t.title and coalesce(status,'Pending')='Pending') then update public.tasks set status='submitted' where id=v_t.id; end if;
end
$function$;


CREATE OR REPLACE FUNCTION public.claim_next_voice_l2_review(p_task_id integer)
 RETURNS TABLE(submission_id integer, worker_uid text, project_title text, source_task_id integer, audio_path text, submitted_at timestamp with time zone, recording_id uuid, duration_seconds integer, rubric jsonb, claimed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_u public.users; v_t public.tasks; v_submission_id integer; v_lifecycle text;
begin
  select * into v_u from public.users where id=auth.uid() for update; if v_u.id is null then raise exception 'Not authenticated'; end if;
  if v_u."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'Platform access required'; end if;
  select * into v_t from public.tasks where id=p_task_id and layer='L2' and status='pending' and ("assignedTo"=v_u.email or "assignedTo"=v_u."uniqueID") for update;
  if v_t.id is null then raise exception 'Reviewer assignment not found'; end if;
  if not app_private.has_project_access(v_t.title) then raise exception 'Project access revoked'; end if;
  select lifecycle_status into v_lifecycle from public.project_lab where project_name=v_t.title order by id desc limit 1;
  if coalesce(v_lifecycle,'active')<>'active' then raise exception 'Project is currently paused or archived'; end if;
  update public.voice_l2_review_claims c set completed_at=now() where c.completed_at is null and exists(select 1 from public.tasks old_t where old_t.id=c.reviewer_task_id and old_t.status<>'pending');
  select c.submission_id into v_submission_id from public.voice_l2_review_claims c join public.submissions s on s.id=c.submission_id where c.reviewer_task_id=v_t.id and c.reviewer_id=v_u.id and c.completed_at is null and s."projectTitle"=v_t.title and coalesce(s.status,'Pending')='Pending' order by c.claimed_at limit 1;
  if v_submission_id is null then
    select s.id into v_submission_id from public.submissions s where s."projectTitle"=v_t.title and coalesce(s.status,'Pending')='Pending' and nullif(trim(coalesce(s."audioData",'')),'') is not null and not exists(select 1 from public.voice_l2_reviews r where r.submission_id=s.id) and not exists(select 1 from public.voice_l2_review_claims c where c.submission_id=s.id and c.completed_at is null) order by s."timestamp",s.id for update skip locked limit 1;
    if v_submission_id is not null then insert into public.voice_l2_review_claims(submission_id,reviewer_task_id,reviewer_id) values(v_submission_id,v_t.id,v_u.id) on conflict on constraint voice_l2_review_claims_submission_id_key do nothing; if not found then v_submission_id:=null; end if; end if;
  end if;
  if v_submission_id is null then return; end if;
  perform app_private.consume_daily_work_slot(v_t.id,v_u.id,'review:'||v_submission_id);
  return query select s.id,s."workerUID",s."projectTitle",s.task_id,s."audioData",s."timestamp",vr.id,coalesce(vr.duration_seconds,vs.duration_seconds,0),case when v_t.rubric_data ? 'rubric' then coalesce(v_t.rubric_data->'rubric','[]'::jsonb) else coalesce(pl.config->'audit_rubric','[]'::jsonb) end,c.claimed_at from public.submissions s join public.voice_l2_review_claims c on c.submission_id=s.id and c.reviewer_task_id=v_t.id and c.reviewer_id=v_u.id and c.completed_at is null left join public.voice_recordings vr on vr.recording_path=s."audioData" and vr.project_title=s."projectTitle" left join public.voice_sessions vs on vs.recording_url=s."audioData" and vs.project_title=s."projectTitle" left join lateral(select p.config from public.project_lab p where p.project_name=s."projectTitle" order by p.id desc limit 1) pl on true where s.id=v_submission_id;
end $function$;


CREATE OR REPLACE FUNCTION public.submit_voice_l2_review(p_task_id integer, p_submission_id integer, p_rubric jsonb, p_decision text, p_feedback text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare
  v_u public.users;
  v_t public.tasks;
  v_claim public.voice_l2_review_claims;
  v_sub public.submissions;
  v_recording_id uuid;
  v_review_id bigint;
  v_remaining integer;
begin
  if p_decision not in ('approved','rejected') then raise exception 'Invalid review decision'; end if;
  select * into v_u from public.users where id=auth.uid() for update;
  if v_u.id is null then raise exception 'Not authenticated'; end if;
  if v_u."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'Platform access required'; end if;

  select * into v_t
  from public.tasks
  where id=p_task_id and layer='L2' and status='pending'
    and ("assignedTo"=v_u.email or "assignedTo"=v_u."uniqueID")
  for update;
  if v_t.id is null then raise exception 'Reviewer assignment not found'; end if;
  if not app_private.has_project_access(v_t.title) then raise exception 'Project access revoked'; end if;

  select * into v_claim
  from public.voice_l2_review_claims
  where submission_id=p_submission_id and reviewer_task_id=v_t.id and reviewer_id=v_u.id and completed_at is null
  for update;
  if v_claim.id is null then raise exception 'Review item is not claimed by this assignment'; end if;

  select * into v_sub from public.submissions
  where id=p_submission_id and "projectTitle"=v_t.title and coalesce(status,'Pending')='Pending'
  for update;
  if v_sub.id is null then raise exception 'Submission unavailable'; end if;

  perform app_private.consume_daily_work_slot(v_t.id,v_u.id,'review:'||p_submission_id);
  select vr.id into v_recording_id
  from public.voice_recordings vr
  where vr.recording_path=v_sub."audioData" and vr.project_title=v_sub."projectTitle"
  order by vr.submitted_at desc
  limit 1;

  insert into public.voice_l2_reviews(submission_id,recording_id,reviewer_task_id,reviewer_id,rubric,decision,feedback)
  values(p_submission_id,v_recording_id,v_t.id,v_u.id,coalesce(p_rubric,'{}'::jsonb),p_decision,nullif(trim(coalesce(p_feedback,'')),''))
  returning id into v_review_id;

  update public.voice_l2_review_claims set completed_at=now() where id=v_claim.id;

  if p_decision='approved' then
    update public.users
    set balance=coalesce(balance,0)+coalesce(v_sub."earnedAmount",0)
    where "uniqueID"=v_sub."workerUID";

    update public.submissions
    set status='Approved', reviewed_at=now(), approved_at=now(), rejected_at=null
    where id=p_submission_id;

    insert into public.submission_payments(submission_id,payment_status,updated_at,updated_by)
    values(p_submission_id,'pending',now(),auth.uid())
    on conflict(submission_id) do nothing;
  else
    update public.submissions
    set status='Rejected', reviewed_at=now(), rejected_at=now(), approved_at=null
    where id=p_submission_id;
  end if;

  if v_recording_id is not null then
    update public.voice_recordings
    set audit_status='audited', latest_verdict=p_decision,
        latest_feedback=nullif(trim(coalesce(p_feedback,'')),''), audited_at=now(), updated_at=now()
    where id=v_recording_id;
  end if;

  select count(*) into v_remaining
  from public.submissions s
  where s."projectTitle"=v_t.title
    and coalesce(s.status,'Pending')='Pending'
    and s."audioData" is not null
    and not exists(select 1 from public.voice_l2_reviews r where r.submission_id=s.id)
    and not exists(select 1 from public.voice_l2_review_claims c where c.submission_id=s.id and c.completed_at is null);

  if v_remaining=0 and exists(select 1 from public.voice_l2_reviews r where r.reviewer_task_id=v_t.id) then
    update public.tasks set status='submitted' where id=v_t.id;
  end if;

  return v_review_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.start_solo_voice_session(p_project text, p_task_id integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_user public.users; v_task public.tasks; v_session uuid; v_mode text;
begin
  select * into v_user from public.users where id=auth.uid() for update;
  if v_user.id is null then raise exception 'Not authenticated'; end if;
  if v_user."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'Platform access required'; end if;
  if not app_private.has_project_access(p_project) then raise exception 'Project access revoked'; end if;
  select coalesce(config->>'mode','') into v_mode from public.project_lab where project_name=p_project and is_published=true order by id desc limit 1;
  if v_mode<>'solo_voice_recording' then raise exception 'Project is not configured for solo recording'; end if;
  select * into v_task from public.tasks where id=p_task_id and title=p_project and status='pending' and layer='L1' and ("assignedTo"=v_user.email or "assignedTo"=v_user."uniqueID") limit 1;
  if v_task.id is null then raise exception 'No active assignment for this project'; end if;
  perform app_private.consume_daily_task_slot(v_task.id,v_user.id);
  select session_id into v_session from public.voice_sessions where project_title=p_project and lower(host_email)=lower(v_user.email) and guest_email is null and status='connected' order by created_at desc limit 1;
  if v_session is null then v_session:=gen_random_uuid(); insert into public.voice_sessions(session_id,project_title,host_email,guest_email,status) values(v_session,p_project,v_user.email,null,'connected'); end if;
  return v_session;
end $function$;


alter table public.voice_sessions add column if not exists host_task_id integer references public.tasks(id) on delete set null;
alter table public.voice_sessions add column if not exists guest_task_id integer references public.tasks(id) on delete set null;
alter table public.voice_queue add column if not exists task_id integer references public.tasks(id) on delete set null;

drop function public.join_voice_session(text);
create function public.join_voice_session(p_project text,p_task_id integer default null)
returns table(user_role text,session_id uuid,peer_email text,queue_id bigint)
language plpgsql security definer set search_path='' as $$
declare u public.users; t public.tasks; candidate public.voice_queue; existing public.voice_queue; sess public.voice_sessions; sid uuid; qid bigint;
begin
 select * into u from public.users where id=auth.uid() for update;
 if u.id is null or u."accountStatus"<>'active' then raise exception 'PLATFORM_ACCESS_REQUIRED'; end if;
 if not app_private.has_project_access(p_project) then raise exception 'PROJECT_ACCESS_REVOKED'; end if;
 select * into t from public.tasks where title=p_project and layer='L1' and status='pending' and lower("assignedTo") in (lower(u.email),lower(u."uniqueID")) and (p_task_id is null or id=p_task_id) order by id limit 1;
 if t.id is null then raise exception 'TASK_NOT_AVAILABLE'; end if;
 if exists(select 1 from public.project_lab where project_name=p_project and (coalesce(lifecycle_status,'active')<>'active' or config->>'mode'='solo_voice_recording')) then raise exception 'PROJECT_NOT_AVAILABLE_FOR_PAIRED_RECORDING'; end if;
 select * into existing from public.voice_queue q where q.project_title=p_project and q.user_uid=u.id::text order by q.created_at desc limit 1 for update;
 if existing.id is not null then
   if existing.task_id is not null and existing.task_id<>t.id and existing.status in ('waiting','matched') then raise exception 'Finish or leave your current task before starting another.'; end if;
   if existing.status='matched' then
     select * into sess from public.voice_sessions vs where vs.session_id=existing.matched_session_id;
     if sess.session_id is not null and sess.status<>'completed' then
       perform app_private.consume_daily_task_slot(t.id,u.id);
       return query select coalesce(existing.role_preference,'Guest'),existing.matched_session_id,case when lower(sess.host_email)=lower(u.email) then sess.guest_email else sess.host_email end,existing.id;return;
     end if;
   elsif existing.status='waiting' then
     perform app_private.consume_daily_task_slot(t.id,u.id);
     update public.voice_queue set task_id=t.id where id=existing.id;
     return query select coalesce(existing.role_preference,'Host'),null::uuid,null::text,existing.id;return;
   end if;
   delete from public.voice_queue where id=existing.id;
 end if;
 perform app_private.consume_daily_task_slot(t.id,u.id);
 select q.* into candidate from public.voice_queue q join public.users other on other.id::text=q.user_uid join public.tasks other_t on other_t.id=q.task_id
 where q.project_title=p_project and q.status='waiting' and q.user_uid<>u.id::text and other."accountStatus"='active' and other_t.status='pending' and app_private.user_has_project_access(other.id,p_project)
 order by q.created_at for update of q skip locked limit 1;
 if candidate.id is not null then
   sid:=gen_random_uuid();
   update public.voice_queue set status='matched',matched_session_id=sid,updated_at=now() where id=candidate.id;
   insert into public.voice_queue(project_title,user_email,user_uid,role_preference,status,matched_session_id,task_id) values(p_project,u.email,u.id::text,'Guest','matched',sid,t.id) returning id into qid;
   insert into public.voice_sessions(session_id,project_title,host_email,guest_email,status,host_task_id,guest_task_id) values(sid,p_project,candidate.user_email,u.email,'connected',candidate.task_id,t.id);
   return query select 'Guest'::text,sid,candidate.user_email,qid;
 else
   insert into public.voice_queue(project_title,user_email,user_uid,role_preference,status,task_id) values(p_project,u.email,u.id::text,'Host','waiting',t.id) returning id into qid;
   return query select 'Host'::text,null::uuid,null::text,qid;
 end if;
end $$;
revoke all on function public.join_voice_session(text,integer) from public,anon;
grant execute on function public.join_voice_session(text,integer) to authenticated;

CREATE OR REPLACE FUNCTION public.start_solo_voice_session(p_project text, p_task_id integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_user public.users; v_task public.tasks; v_session uuid; v_mode text;
begin
  select * into v_user from public.users where id=auth.uid() for update;
  if v_user.id is null then raise exception 'Not authenticated'; end if;
  if v_user."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'Platform access required'; end if;
  if not app_private.has_project_access(p_project) then raise exception 'Project access revoked'; end if;
  select coalesce(config->>'mode','') into v_mode from public.project_lab where project_name=p_project and is_published=true order by id desc limit 1;
  if v_mode<>'solo_voice_recording' then raise exception 'Project is not configured for solo recording'; end if;
  select * into v_task from public.tasks where id=p_task_id and title=p_project and status='pending' and layer='L1' and ("assignedTo"=v_user.email or "assignedTo"=v_user."uniqueID") limit 1;
  if v_task.id is null then raise exception 'No active assignment for this project'; end if;
  perform app_private.consume_daily_task_slot(v_task.id,v_user.id);
  select session_id into v_session from public.voice_sessions where project_title=p_project and lower(host_email)=lower(v_user.email) and guest_email is null and status='connected' and host_task_id=v_task.id order by created_at desc limit 1;
  if v_session is null then v_session:=gen_random_uuid(); insert into public.voice_sessions(session_id,project_title,host_email,guest_email,status,host_task_id) values(v_session,p_project,v_user.email,null,'connected',v_task.id); end if;
  return v_session;
end $function$;


CREATE OR REPLACE FUNCTION public.complete_voice_session(p_session uuid, p_recording_path text, p_duration integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private', 'pg_temp'
AS $function$
declare v_email text; v_s public.voice_sessions; v_profile public.users; v_task public.tasks; v_caller public.users;
begin
 select * into v_caller from public.users where id=auth.uid();
 if v_caller.id is null then raise exception 'Not authenticated'; end if;
 if v_caller."accountStatus"<>'active' and not app_private.is_admin() then raise exception 'Platform access required'; end if;
 v_email:=v_caller.email;
 select * into v_s from public.voice_sessions where session_id=p_session;
 if v_s.session_id is null or not coalesce(lower(v_s.host_email)=lower(v_email) or lower(v_s.guest_email)=lower(v_email),false) then raise exception 'Not a session participant'; end if;
 perform id from public.users where lower(email)=lower(v_s.host_email) or lower(email)=lower(v_s.guest_email) order by id for update;
 select * into v_s from public.voice_sessions where session_id=p_session for update;
 if v_s.session_id is null or not (lower(v_s.host_email)=lower(v_email) or lower(v_s.guest_email)=lower(v_email)) then raise exception 'Not a session participant'; end if;
 if not app_private.has_project_access(v_s.project_title) then raise exception 'Project access revoked'; end if;
 if p_duration<0 or p_duration>14400 then raise exception 'Invalid duration'; end if;
 if p_recording_path is null or split_part(p_recording_path,'_',1)<>p_session::text then raise exception 'Invalid recording path'; end if;
 if v_s.status<>'completed' then
   update public.voice_sessions set status='completed',recording_url=p_recording_path,duration_seconds=p_duration,ended_at=now() where session_id=p_session;
   for v_profile in select * from public.users where lower(email)=lower(v_s.host_email) or (v_s.guest_email is not null and lower(email)=lower(v_s.guest_email)) loop
     if app_private.user_has_project_access(v_profile.id,v_s.project_title) then
       v_task:=null;
       select * into v_task from public.tasks where title=v_s.project_title and layer='L1' and status='pending' and ("assignedTo"=v_profile.email or "assignedTo"=v_profile."uniqueID") and (case when lower(v_profile.email)=lower(v_s.host_email) then v_s.host_task_id else v_s.guest_task_id end is null or id=case when lower(v_profile.email)=lower(v_s.host_email) then v_s.host_task_id else v_s.guest_task_id end) order by id limit 1 for update;
       if v_task.id is not null then
         perform app_private.consume_daily_task_slot(v_task.id,v_profile.id);
         if not exists(select 1 from public.submissions where "workerUID"=v_profile."uniqueID" and "projectTitle"=v_task.title and "audioData"=p_recording_path) then
           insert into public.submissions("workerUID","projectTitle","earnedAmount","audioData",status,task_id)
           values(v_profile."uniqueID",v_task.title,coalesce(v_task.price,0),p_recording_path,'Pending',v_task.id);
         end if;
         update public.tasks set status='submitted' where id=v_task.id;
       end if;
     end if;
   end loop;
   delete from public.voice_queue where matched_session_id=p_session;
 end if;
end;
$function$;


notify pgrst, 'reload schema';
